/-- Collect constant names appearing in an expression. -/
def collectExprConsts (e : Lean.Expr) : Lean.NameSet :=
  let fromConsts :=
    e.foldConsts (init := Lean.NameSet.empty) fun n acc =>
      acc.insert n
  fromConsts.union (projHeads e)

